mapper.select:
select idusuario, clave2 as clave, habilitado
from seguridad.usuarios
where usuario=#{usuario}

select idusuario, idpersona, usuario, clave, habilitado
from seguridad.usuarios
where idusuario=#{id}

select idusuario, usuario
from seguridad.usuarios join seguridad.usuariosroles using(idusuario)
where seguridad.usuariosroles.idrol=21

select idusuario, idpersona, primerapellido, segundoapellido, primernombre, segundonombre, usuario, clave
from seguridad.usuarios join nucleo.personas using(idpersona)
where idusuario=#{id}
